    public static void petInteract(Player player, Entity pet) {
        UUID petOwnerId = getOwnerOfPet(pet.getUniqueId());
        if (petOwnerId == null) return;
        long now = System.currentTimeMillis();
        long cooldown = interactionCooldowns.getOrDefault(player.getUniqueId(), 0L);
        if (now < cooldown) return;
        interactionCooldowns.put(player.getUniqueId(), now + 2000L);
        Player owner = org.bukkit.Bukkit.getPlayer(petOwnerId);
        String ownerName = owner != null ? owner.getName() : "Unknown";
        if (!petOwnerId.equals(player.getUniqueId())) {
            String msg = ACTIONBAR_NOT_OWNER.replace("{owner}", ownerName);
            player.sendActionBar(legacyMessage(msg));
        } else {
            if (pet instanceof Allay allay && tryGiveItemToAllay(player, allay)) {
                player.sendActionBar(legacyMessage(ACTIONBAR_OWNER));
                return;
            }
            player.sendActionBar(legacyMessage(ACTIONBAR_OWNER));
        }
        pet.getWorld().spawnParticle(Particle.HEART, pet.getLocation().add(0, 1, 0), 3, 0.3, 0.3, 0.3, 0.1);
        pet.getWorld().playSound(pet.getLocation(), getPetSound(pet.getType()), 0.5f, 1.2f);
    }

    private static boolean tryGiveItemToAllay(Player player, Allay allay) {
        ItemStack inHand = player.getInventory().getItemInMainHand();
        if (inHand == null || inHand.getType() == Material.AIR) {
            return false;
        }

        EntityEquipment equipment = allay.getEquipment();
        if (equipment == null) {
            return false;
        }

        ItemStack previous = equipment.getItemInMainHand();
        ItemStack newItem = inHand.clone();
        newItem.setAmount(1);
        equipment.setItemInMainHand(newItem);

        if (inHand.getAmount() <= 1) {
            player.getInventory().setItemInMainHand(new ItemStack(Material.AIR));
        } else {
            inHand.setAmount(inHand.getAmount() - 1);
            player.getInventory().setItemInMainHand(inHand);
        }

        if (previous != null && previous.getType() != Material.AIR) {
            var leftovers = player.getInventory().addItem(previous);
            for (ItemStack leftover : leftovers.values()) {
                player.getWorld().dropItemNaturally(player.getLocation(), leftover);
            }
        }

        allay.getWorld().spawnParticle(Particle.HAPPY_VILLAGER, allay.getLocation().add(0, 0.8, 0), 4, 0.2, 0.2, 0.2, 0.01);
        allay.getWorld().playSound(allay.getLocation(), Sound.ENTITY_ITEM_PICKUP, 0.6f, 1.3f);
        return true;
    }
    
