    public static boolean isCosmeticParrot(Entity entity) {
        if (!(entity instanceof org.bukkit.entity.Parrot)) return false;
        return entity.getPersistentDataContainer().has(COSMETIC_PARROT_KEY, PersistentDataType.BYTE);
    }

    public static UUID getOwnerOfPet(UUID petId) {
        for (Map.Entry<UUID, UUID> entry : activePets.entrySet()) {
            if (entry.getValue().equals(petId)) {
                return entry.getKey();
            }
        }
        return null;
    }
    
