    public static UUID getActivePetId(Player player) {
        return player != null ? activePets.get(player.getUniqueId()) : null;
    }

    public static String getActiveCosmeticId(UUID playerId) {
        return playerId == null ? null : petCosmeticIds.get(playerId);
    }

    public static void unequipActivePet(Player player) {
        if (player == null) {
            return;
        }
        UUID playerId = player.getUniqueId();
        UUID petId = activePets.remove(playerId);
        petCosmeticIds.remove(playerId);
        interactionCooldowns.remove(playerId);

        if (petId != null) {
            try {
                Entity entity = player.getServer().getEntity(petId);
                if (entity != null) {
                    entity.remove();
                }
            } catch (Exception ignored) {
            }
        }

        if (player.getShoulderEntityLeft() != null) {
            player.setShoulderEntityLeft(null);
        }
        if (player.getShoulderEntityRight() != null) {
            player.setShoulderEntityRight(null);
        }
    }
    
