    public static void removeAllPets() {
        activePets.clear();
        petCosmeticIds.clear();
        petCustomNames.clear();
        interactionCooldowns.clear();
    }

    public static void setCustomPetName(UUID playerId, String name) {
        if (playerId == null) {
            return;
        }
        if (name == null || name.isBlank()) {
            petCustomNames.remove(playerId);
        } else {
            petCustomNames.put(playerId, name);
        }
    }

    public static String getCustomPetName(UUID playerId) {
        return playerId == null ? null : petCustomNames.get(playerId);
    }

    private static void applyCustomName(Player player, Entity entity, boolean showNameByDefault) {
        if (!(entity instanceof LivingEntity living)) {
            return;
        }
        String customName = getCustomPetName(player.getUniqueId());
        if (customName == null || customName.isBlank()) {
            living.customName(null);
            living.setCustomNameVisible(false);
            return;
        }
        living.customName(legacyMessage(customName));
        living.setCustomNameVisible(showNameByDefault);
    }
    
