    public static void teleportPetToPlayer(Player player) {
        UUID petId = activePets.get(player.getUniqueId());
        if (petId == null) return;
        
        Entity pet = player.getServer().getEntity(petId);
        if (pet != null) {
            Location targetLoc = player.getLocation().add(2, 0, 2);
            pet.teleportAsync(targetLoc);
        }
    }

    private static Attribute resolveAttribute(String... names) {
        for (String name : names) {
            try {
                Field field = Attribute.class.getField(name);
                Object value = field.get(null);
                if (value instanceof Attribute attribute) {
                    return attribute;
                }
            } catch (Exception ignored) {
            }
            try {
                if (Attribute.class.isEnum()) {
                    @SuppressWarnings({"rawtypes", "unchecked"})
                    Object value = Enum.valueOf((Class) Attribute.class, name);
                    if (value instanceof Attribute attribute) {
                        return attribute;
                    }
                }
            } catch (Exception ignored) {
            }
        }
        return null;
    }

    private static Location getGroundedLocation(Location source) {
        if (source == null || source.getWorld() == null) {
            return source;
        }
        int groundY = source.getWorld().getHighestBlockYAt(source.getBlockX(), source.getBlockZ());
        return new Location(source.getWorld(), source.getX(), groundY + 1.0, source.getZ(), source.getYaw(), source.getPitch());
    }

    private static boolean isNaturallyFlyingPet(Entity entity) {
        return switch (entity.getType()) {
            case ALLAY, BAT, BEE, BLAZE, GHAST, PARROT, PHANTOM, VEX -> true;
            default -> false;
        };
    }

    private static Location getFollowLocation(Location playerLoc) {
        org.bukkit.util.Vector direction = playerLoc.getDirection().setY(0).normalize();
        if (direction.lengthSquared() == 0) {
            direction = new org.bukkit.util.Vector(0, 0, 1);
        }
        org.bukkit.util.Vector side = direction.clone().crossProduct(new org.bukkit.util.Vector(0, 1, 0)).normalize();
        return playerLoc.clone().add(side.multiply(-1.2)).add(direction.multiply(-1.0));
    }

